INSERT INTO postings (id, company, title, track, location, source_url, salary, score, decision, confidence, remote_eligibility, seniority_detected, matched_requirements, gaps, one_line_reason, tailored_summary, sponsorship_country, sponsorship_verified, sponsorship_evidence, status, status_changed_at, date_found, tailored_cv_url, tailored_cv_filename) VALUES ('anthropic-security-engineer-corporate-security', 'Anthropic', 'Security Engineer, Corporate Security', 'sponsorship', 'San Francisco, CA / Seattle, WA / New York, NY / Washington, DC (office-based/hybrid, not remote)', 'https://job-boards.greenhouse.io/anthropic/jobs/5397319008', '$320,000–$405,000 USD/year', 63, 'review', 'medium', 'n/a (sponsorship-relocation track) — sponsorship verified verbatim on Anthropic''s own posting.', 'Senior, hands-on IC — candidate''s 8+ years fits, no explicit years-minimum stated', '["Identity and access management expertise","Zero-trust access controls","Python/scripting proficiency","Threat modeling"]', '["Core of role is endpoint security engineering (macOS/Windows/Linux/ChromeOS, MDM) — candidate''s real experience is cloud security, not endpoint device management","Office-based in one of 4 US cities, not remote","Anthropic states it can''t sponsor for every role/candidate even when it tries"]', 'Verified sponsorship language directly from Anthropic''s own posting and an exceptional salary, but the role''s actual day-to-day (endpoint/MDM security) is a real mismatch with candidate''s cloud/GRC background.', 'If pursuing, lead with IAM/zero-trust access control work from Vigilsec and Python scripting for security automation; be upfront that hands-on MDM/endpoint fleet management is not part of your background.', 'USA', 1, 'We do sponsor visas! However, we aren''t able to successfully sponsor visas for every role and every candidate. But if we make you an offer, we will make every reasonable effort to get you a visa, and we retain an immigration lawyer to help with this. (quoted verbatim from Anthropic''s own Greenhouse posting)', 'Pending Review', NULL, '2026-09-21T22:45:00Z', NULL, NULL);
INSERT INTO postings (id, company, title, track, location, source_url, salary, score, decision, confidence, remote_eligibility, seniority_detected, matched_requirements, gaps, one_line_reason, tailored_summary, sponsorship_country, sponsorship_verified, sponsorship_evidence, status, status_changed_at, date_found, tailored_cv_url, tailored_cv_filename) VALUES ('anthropic-staff-security-engineer-risk-engineering', 'Anthropic', 'Staff+ Security Engineer, Risk Engineering', 'sponsorship', 'San Francisco, CA / New York, NY / Seattle, WA — hybrid, expect all staff in office ≥25% of the time', 'https://job-boards.greenhouse.io/anthropic/jobs/5250052008', '$320,000–$405,000 USD/year', 74, 'review', 'medium', 'n/a (sponsorship-relocation track) — sponsorship verified verbatim on Anthropic''s own posting.', 'Staff+ IC, minimum 8 years security/software engineering required — a genuine stretch competitively', '["Risk assessment and quantification — matches GRC/risk advisory background","Infrastructure/cloud security — matches AWS Security Hub/GuardDuty/Config work at Vigilsec","Identity/secrets management exposure","Security automation"]', '["Deep systems programming (Go/Rust/C/C++) requested alongside Python — candidate''s automation work is Python/Bash","Developer security / software supply-chain depth not strongly evidenced","Staff+ level at a top AI lab is highly competitive — treat as a stretch application"]', 'Strongest domain fit of the sponsorship-track candidates — GRC/risk/cloud-security overlap is real and sponsorship is verified verbatim — but Staff+ bar and systems-programming ask make it a genuine stretch.', 'Lead with risk assessment/quantification from GRC advisory work and cloud security automation at Vigilsec. Be upfront that Python/Bash is your automation depth, not Go/Rust/C/C++.', 'USA', 1, 'We do sponsor visas! However, we aren''t able to successfully sponsor visas for every role and every candidate. But if we make you an offer, we will make every reasonable effort to get you a visa. (quoted verbatim from Anthropic''s own Greenhouse posting)', 'Pending Review', NULL, '2026-09-21T22:45:00Z', NULL, NULL);
INSERT INTO postings (id, company, title, track, location, source_url, salary, score, decision, confidence, remote_eligibility, seniority_detected, matched_requirements, gaps, one_line_reason, tailored_summary, sponsorship_country, sponsorship_verified, sponsorship_evidence, status, status_changed_at, date_found, tailored_cv_url, tailored_cv_filename) VALUES ('checkmk-devsecops-cloud-security', 'Checkmk (Checkmk GmbH)', 'DevSecOps (m/f/d) Cloud Security', 'italy-remote', 'Remote / high flexibility with Munich, Germany office — team distributed across Germany, Italy, Austria, France, Spain, Poland, USA, Singapore, Malaysia', 'https://checkmk-gmbh.jobs.personio.com/job/2526687', 'EUR 85,000-105,000/year', 85, 'apply', 'medium', 'likely eligible — Checkmk publicly states its team is distributed across Germany, Italy, Austria, France, Spain, Poland, USA, Singapore and Malaysia, explicitly including Italy. Could not load the live Personio posting directly this run to confirm the exact eligible-country list for this specific requisition.', 'Senior IC — candidate''s 8+ years comfortably covers it', '["AWS IAM boundaries, GuardDuty/Macie-style threat detection","CI/CD security integration and shift-left automation","Kubernetes/EKS security hardening","Python/Bash scripting for security automation","Business-fluent English required, German only ''a plus''"]', '["AWS Organizations/Service Control Policies not directly evidenced","Exact eligible-country list for this requisition not directly confirmed","German listed as a plus, not required — not a hard-filter issue"]', 'Best domain fit — DevSecOps/cloud security role heavy on AWS IAM, CI/CD security gates, and Kubernetes/EKS hardening, English-only language bar, real salary well above floor, Checkmk explicitly lists Italy among the countries its team works from.', 'Lead with EKS/Kubernetes security hardening and AWS Security Hub/GuardDuty/Config automation plus Terraform-based CI/CD policy gates. Confirm Italy is approved for this specific requisition before investing further time.', NULL, 0, NULL, 'Pending Review', NULL, '2026-09-21T10:15:00Z', NULL, NULL);
INSERT INTO postings (id, company, title, track, location, source_url, salary, score, decision, confidence, remote_eligibility, seniority_detected, matched_requirements, gaps, one_line_reason, tailored_summary, sponsorship_country, sponsorship_verified, sponsorship_evidence, status, status_changed_at, date_found, tailored_cv_url, tailored_cv_filename) VALUES ('form3-senior-cloud-security-engineer-ai-resilience', 'Form3', 'Senior Cloud Security Engineer - AI Resilience & Security Enhancements (Contract)', 'italy-remote', '100% Remote (Europe) — posting explicitly names Italy as one of the countries hired from', 'https://boards-api.greenhouse.io/v1/boards/form3/jobs/8628358002', 'unclear — not stated (contract rate not listed)', 89, 'apply', 'high', 'eligible — posting states verbatim: "Specifically hiring from: Austria, Bulgaria, Croatia, Cyprus, Estonia, Greece, Hungary, Italy, Latvia, Lithuania, Malta, Romania, Slovakia, and Slovenia." Italy named explicitly.', 'Senior level, hands-on IC — candidate''s 8+ years fits well', '["AWS platform security","IAM, RBAC, least-privilege models","CI/CD pipeline security","Software supply chain security","Kubernetes and Linux expertise","Infrastructure as Code / policy-as-code"]', '["This is a CONTRACT position, not permanent — confirm this fits before applying","AI/ML platform security controls (desirable, not required) not evidenced","Cryptographic key management depth not strongly evidenced","No salary/day-rate stated"]', 'Best-fitting posting found — Italy explicitly named as an eligible hire country, strong AWS/IAM/CI-CD/Kubernetes overlap, senior level matched. Only caveat is it''s a contract, not permanent, role.', 'Lead with AWS Security Hub/GuardDuty/Config automation, Terraform-based CI/CD policy gates, and EKS/Kubernetes hardening. Confirm the contract term/day-rate meets expectations before applying.', NULL, 0, NULL, 'Pending Review', NULL, '2026-09-21T23:00:00Z', NULL, NULL);
INSERT INTO postings (id, company, title, track, location, source_url, salary, score, decision, confidence, remote_eligibility, seniority_detected, matched_requirements, gaps, one_line_reason, tailored_summary, sponsorship_country, sponsorship_verified, sponsorship_evidence, status, status_changed_at, date_found, tailored_cv_url, tailored_cv_filename) VALUES ('jobandtalent-senior-application-security-engineer', 'Job&Talent', 'Senior Application Security Engineer', 'italy-remote', 'Remote, ±1hr CET flexibility (HQ Madrid)', 'https://jobs.lever.co/jobandtalent/3b64145a-39a1-41c9-8b65-f8d5c9c1d5b6', 'unclear — not listed', 56, 'review', 'low', 'unclear — CET-timezone flexible (Italy fits timezone-wise) but eligible countries not explicitly stated', 'Senior, 3-4+ years required — candidate exceeds on paper', '["general security engineering background","CI/CD security automation exposure"]', '["role is a dedicated Application Security specialization — not one of the candidate''s core target families and not strongly evidenced","no salary stated"]', 'Seniority and general security background fit, but this is a deep AppSec specialization the candidate hasn''t demonstrated — borderline.', 'If pursuing, lead with automated vulnerability scanning pipeline work at Soft Solutions S.R.L. and CI/CD policy gates at Vigilsec; honestly flag that dedicated SAST/threat-modeling/pen-testing depth is limited.', NULL, 0, NULL, 'Applied', '2026-09-21T00:00:00Z', '2026-09-21T00:00:00Z', NULL, NULL);
INSERT INTO postings (id, company, title, track, location, source_url, salary, score, decision, confidence, remote_eligibility, seniority_detected, matched_requirements, gaps, one_line_reason, tailored_summary, sponsorship_country, sponsorship_verified, sponsorship_evidence, status, status_changed_at, date_found, tailored_cv_url, tailored_cv_filename) VALUES ('nebius-infrastructure-security-engineer', 'Nebius', 'Senior/Staff Infrastructure Security Engineer', 'italy-remote', 'Remote - Europe', 'https://job-boards.greenhouse.io/embed/job_app?for=nebius&token=4537289101', 'unclear — not listed in posting', 78, 'apply', 'medium', 'likely eligible — posting is titled and scoped "Remote - Europe" with no country exclusions listed; exact Italy inclusion isn''t spelled out verbatim.', 'Senior/Staff IC, 6+ years infrastructure/cloud/network security required — candidate''s 8+ years clears this', '["Cloud security architecture (containers, VMs, serverless, Kubernetes)","IAM","Security automation scripting (Python, Bash)","Infrastructure-as-code security (Terraform)","Kubernetes hardening"]', '["Go scripting not evidenced","Linux-level hardening (apparmor/seccomp) not directly evidenced","Exact eligible-country list not spelled out — confirm Italy before investing significant application time","No salary stated"]', 'Verified live Greenhouse posting, English-only, Remote-Europe scope with strong IAM/Terraform/Kubernetes-hardening overlap and seniority well matched.', 'Lead with AWS Security Hub/GuardDuty/Config automation and Terraform-based CI/CD policy gates, plus EKS/Kubernetes hardening and Python/Bash security automation scripting.', NULL, 0, NULL, 'Pending Review', NULL, '2026-09-21T21:30:00Z', NULL, NULL);
INSERT INTO postings (id, company, title, track, location, source_url, salary, score, decision, confidence, remote_eligibility, seniority_detected, matched_requirements, gaps, one_line_reason, tailored_summary, sponsorship_country, sponsorship_verified, sponsorship_evidence, status, status_changed_at, date_found, tailored_cv_url, tailored_cv_filename) VALUES ('prima-cyber-security-governance-specialist', 'Prima', 'Cyber Security Governance Specialist', 'italy-remote', 'Milan, Italy (remote flexible — Italy/Spain/UK)', 'https://jobs.eu.lever.co/prima/47cfe444-120e-477f-b169-6dff57383874', '€40,000–€50,000/year', 84, 'apply', 'high', 'eligible', 'Mid-level IC (2+ yrs min) — candidate exceeds the bar', '["ISO 27001 gap assessments","GDPR compliance work","risk assessments & audits","governance framework experience"]', '["DORA specifics not confirmed","no formal BCM/DR ownership","AI-governance tooling unconfirmed","CISSP/CISM/CRISC not held (nice-to-have only)"]', 'Strong GRC/ISO27001/GDPR overlap, Italy-based remote role, salary within range — best match found this run.', 'Lead with ISO 27001 gap-assessment delivery via ciso.ikenga.ng and GDPR/audit-evidence work at Soft Solutions S.R.L.; acknowledge DORA and formal BCM as growth areas.', NULL, 0, NULL, 'Applied', '2026-09-21T00:00:00Z', '2026-09-20T00:00:00Z', NULL, 'Sebastine_Nnanemere_CV_Prima.pdf');
