INSERT INTO postings (id, company, title, track, location, source_url, salary, score, decision, confidence, remote_eligibility, seniority_detected, matched_requirements, gaps, one_line_reason, tailored_summary, sponsorship_country, sponsorship_verified, sponsorship_evidence, status, status_changed_at, date_found, tailored_cv_url, tailored_cv_filename) VALUES ('transficc-security-compliance-specialist', 'TransFICC', 'Security Compliance Specialist', 'italy-remote', 'Remote First (office in London) — flexible remote working locations within UK/Europe', 'https://jobs.ashbyhq.com/transficc/8a1232f8-e84b-4bdd-a861-73bb138078d9', 'up to £75,000 + shares + benefits', 82, 'apply', 'medium', 'eligible (broad UK/Europe remote, Italy not confirmed by name but not excluded)', '4+ years required — candidate exceeds', '["GRC/compliance experience","ISO 27001 and SOC 2 process leadership","security questionnaire response","audit coordination"]', '["DORA/NIS2 specifics not confirmed hands-on","CISSP/CISM not held"]', 'Strong GRC/ISO27001/SOC2 overlap, broad UK/Europe remote eligibility, real salary stated — second-best match in the tracker.', 'Lead with ISO 27001/SOC 2 process ownership and audit coordination; be upfront that DORA/NIS2 exposure is developing rather than deep.', NULL, 0, NULL, 'Applied', '2026-09-21T00:00:00Z', '2026-09-21T00:00:00Z', NULL, NULL);
INSERT INTO postings (id, company, title, track, location, source_url, salary, score, decision, confidence, remote_eligibility, seniority_detected, matched_requirements, gaps, one_line_reason, tailored_summary, sponsorship_country, sponsorship_verified, sponsorship_evidence, status, status_changed_at, date_found, tailored_cv_url, tailored_cv_filename) VALUES ('usergems-senior-security-engineer', 'UserGems', 'Senior Security Engineer', 'italy-remote', 'Remote, Europe', 'https://job-boards.greenhouse.io/usergems/jobs/6018876004', '€80,000–€100,000/year', 74, 'review', 'medium', 'eligible (assumed — ''Remote Europe'', Italy not explicitly excluded)', 'Senior, first dedicated security hire — matches', '["SOC 2 / ISO 27001 familiarity","AWS working knowledge","vulnerability management","incident response"]', '["posting''s ''critical requirement'' is sole end-to-end ownership of a zero-exception SOC2/ISO audit — a real stretch","secure code review / pen-testing depth unconfirmed"]', 'Strong comp and scope, but the one ''critical'' bar (sole zero-exception audit ownership) is a real stretch — worth a closer read.', 'Lead with SOC2/ISO27001 compliance automation and independent ISO27001 gap-assessment delivery; be honest that you''ve owned remediation/evidence rather than sole audit ownership.', NULL, 0, NULL, 'Applied', '2026-09-21T00:00:00Z', '2026-09-20T00:00:00Z', NULL, 'Sebastine_Nnanemere_CV_UserGems.pdf');
INSERT INTO postings (id, company, title, track, location, source_url, salary, score, decision, confidence, remote_eligibility, seniority_detected, matched_requirements, gaps, one_line_reason, tailored_summary, sponsorship_country, sponsorship_verified, sponsorship_evidence, status, status_changed_at, date_found, tailored_cv_url, tailored_cv_filename) VALUES ('ygo-cloud-security-engineer', 'YGO', 'Cloud Security Engineer', 'italy-remote', 'Remote, EU', 'https://jobs.ashbyhq.com/ygo/e0b8615d-77e0-436d-86a1-99cdba9c8b53', 'unclear — not listed', 77, 'apply', 'medium', 'eligible (assumed — EU-wide remote, Italy not confirmed excluded)', '5+ years required — candidate exceeds', '["cloud security fundamentals","IAM","incident investigation","5+ years hands-on security"]', '["application security depth (SAST/DAST, secure code review) not strongly evidenced","''engineering background essential'' — candidate is automation/scripting-strong but not software-engineer by background","no salary stated"]', 'Good IAM/cloud/IR overlap and EU remote eligibility, but appsec depth and the engineering-background bar are open questions.', 'Lead with IAM governance, incident response, and EKS/cloud hardening; be upfront that appsec testing is a growth area.', NULL, 0, NULL, 'Applied', '2026-09-21T00:00:00Z', '2026-09-20T00:00:00Z', NULL, 'Sebastine_Nnanemere_CV_YGO.pdf');
